-- Aggregate values bootstrap
UPDATE countries c
LEFT JOIN (
  SELECT country_id, SUM(population) AS total_population, COUNT(*) AS city_count FROM cities GROUP BY country_id
) cityAgg ON cityAgg.country_id = c.id
SET c.total_population = IFNULL(cityAgg.total_population, 0), c.economy_score = 55.00, c.military_power = 1200;

UPDATE regions r
LEFT JOIN (SELECT region_id, COUNT(*) AS city_count, SUM(population) AS pop FROM cities GROUP BY region_id) agg ON agg.region_id = r.id
SET r.city_count = IFNULL(agg.city_count, 0), r.population = IFNULL(agg.pop, 0);

